"""Save scientific report from completed NEW screw_bag industrial-source test.

Requires actual pinned MVTec screw_bag source photographs 134 SHA-verified,
real ResNet18 ImageNet weights, 134 frozen image-only ResNet18+HSV features,
24 only-normal training, 20 only-normal calibration with test labels NEVER
seen during scoring, 90 genuinely heldout source photos 30 correct/30 logical/
30 structural independently MVTec-author labelled. No new inference or tune.
Save ONLY compact aggregate and stable SHA receipts into SWAAG research Git;
original 194MB copyrighted source photos, patch tensors, per-image IDs, source
labels, official model weights and all raw predictions remain under /data/var.
"""
from pathlib import Path
import json,hashlib,statistics
SRC=Path('/data/var/perceptual-independent-20261024/mvtec-loco-screwbag-20261025')
DOC=Path(__file__).resolve().parents[2]/'docs/research'
OUT=DOC/'perceptual-mvtec-screwbag-new-spatial-anomaly-evidence-2026-10-25.json'
REPORT=DOC/'perceptual-mvtec-screwbag-padim-spatial-original-photos-2026-10-25.md'
MODES=['ResNet18_global_cosine_nearest_normal','ResNet18_spatial_gaussian_mahalanobis_max','ResNet18_spatial_gaussian_mahalanobis_p95','HSV_spatial_color_nearest_normal']

def load(name):
 data=(SRC/name).read_bytes();return json.loads(data),hashlib.sha256(data).hexdigest()

def pct(x):return 'n/a' if x is None else f'{x*100:.1f}%'

def main():
 if OUT.exists() or REPORT.exists():print('REAL_NEW_SCREWBAG_REPORT_ALREADY_EXISTS_PRESERVE');return
 selection,hselection=load('source_frozen_pre_analysis_selection_20261025.json')
 receipts,hreceipts=load('original_source_image_134_SHA256_receipts_20261025.json')
 features,hfeatures=load('134_source_pixelonly_resnet18_imagenet_hsv_features_20261025.json')
 frozen,hfrozen=load('134_screwbag_normalonly_resnet_global_padim_HSV_scores_frozen_20261025.json')
 labels,hlabels=load('90_screwbag_original_heldout_good_logical_structural_confusions_20261025.json')
 assert len(selection['selected'])==len(receipts['completed'])==len(features['results'])==len(frozen['per_source_anonymous_image_score'])==134
 assert features['status']==frozen['status']=='complete'
 assert features['source_selection_sha256']==frozen['source_media_selection_sha256']==hselection
 assert frozen['frozen_pixel_model_features_SHA256']==hfeatures
 assert labels['source_SHA256']['official_source_selection']==hselection
 assert labels['source_SHA256']['actual_original_image_only_ResNet18_HSV_feature_receipts']==hfeatures
 assert labels['source_SHA256']['normal_only_frozen_134_predictions_and_thresholds_before_gold']==hfrozen
 assert labels['source_original_n']=={'train_normal':24,'validation_normal':20,'heldout_good':30,'heldout_logical':30,'heldout_structural':30,'new_source_photos_total':134}
 assert list(labels['full_results'])==MODES
 compact={};rows=[]
 for mode in MODES:
  a=labels['full_results'][mode];logical=a['logical_vs_clean'];struct=a['structural_vs_clean'];both=a['all_anomalies_vs_clean']
  for n,row in [('logical_vs_clean',logical),('structural_vs_clean',struct),('all_anomalies_vs_clean',both)]:
   assert (row['TP']+row['FN'],row['FP']+row['TN'])==(60 if n=='all_anomalies_vs_clean' else 30,30)
  compact[mode]=a
  rows.append(f"| {mode.replace('_',' ')} | {logical['TP']}/30 | {struct['TP']}/30 | {both['FP']}/30 | {both['FN']}/60 | {pct(both['test_AUROC'])} | {both['original_source_image_stratified_bootstrap95']['AUROC']} |")
 rep={'date':'2026-10-25','status':'PARTIAL: fresh independent MVTec original screw bag product, externally source-normal/logical/structural class judged against spatial Gaussian pretrained ResNet18 and same-normal-budget alternatives, not a general CAD/photorealism judge','source_publication':'MVTec LOCO AD (Bergmann et al., IJCV 2022) original Screw Bag product family','source_release':'Rafa612/mvtec_loco pinned HF original-source replica revision839fee8178c10d2e50afddc671238ba85d9975d9','license':'Creative Commons Attribution-NonCommercial-ShareAlike 4.0. No right to reuse in commercial product. All photos stay outside Git.','research_provenance_SHA256':{'new_normal_only_sample_predeclared_before_data':hselection,'134_original_raw_media_SHA_receipt':hreceipts,'134_pixel_only_ResNet18_HSV_features_before_any_test_labels':hfeatures,'24normal_spatial_distribution_plus20normal_calibrated_134_scores_before_test_gold':hfrozen,'external_test_good_logical_structural_90_result':hlabels},'original_photo_counts':labels['source_original_n'],'data_source_ground_truth':'Original MVTec author-supplied normal vs logical vs structural original test directory labels, not independent new human blind visual approval, all 90 test photos separate from 24 train/20 validation','pretrained_model_checkpoint':'Torchvision official ResNet18 ImageNet1K V1 SHA256 f37072fd47e89c5e827621c5baffa7500819f7896bbacec160b1a16c560e07ec','normal_calibration':'Empirical 95th percentile among exactly 20 original source normal validation photographs separately for four predeclared image-only methods, not tuned with defect source labels','architecture':'A research PaDiM-inspired per-pixel Gaussian 32 selected channels from frozen layers1/2/3 on 28x28 grid plus 0.01 covariance ridge, image p95 or max; NOT original official PaDiM or EfficientAD benchmark. Also 512D pretrained global ResNet18 cosine and original HSV spatial histogram with same 24 normal memory and 20 normal calibration photos','heldout_original_source_tp_fp_fn_tn_and_CI':compact,'source_original_134_pixels_resnet_inference_seconds':features.get('wall_seconds'),'source_original_134_pixel_model_peak_RSS_KB':features.get('peak_rss_kb'),'normal_only_distribution_model_score_compute_seconds':frozen.get('elapsed_seconds'),'GPU_allocated':False,'owned_original_data_isolation':'Source original MVTec full-resolution images, per-file original names, all pixel embeddings, source normal distribution parameters, author images/annotations and pretrained model weights kept under /data/var; only scripts/aggregate result source SHA in project Git','limitations':['Only one third original MVTec object family (screw bags), distinct from SWAAG prior splicing connectors/pushpins but still same creator lab/source photographic domain; source scores do not quantify external unseen manufacturer generalization.','Ground truth labels from original source dataset authors; no new blinded human review of defect pixel regions and actual machine CAD specifications.','Normal-only threshold set using just 20 source normal validation; 30 heldout normal controls too few to bound rare false alerts.','Full ImageNet1K pretraining cost and possibly MVTec contamination not quantified; HSV no-pretraining baseline not equally resourced at external model pretraining scale.','Per-pixel Gaussian with only 24 independent train normals and 32 dimensions needs 0.01 shrinkage; spatial alignment variance could cause errors; this is not the official optimized PaDiM algorithm.','A source logical flaw such as wrong count or invalid placement can be missed despite intact image/conv anomaly scores; no visual model currently tested replaces actual source schematic/assembled CAD and physical support graph.','No physical load-bearing, geometry transforms, manufactured assembly tolerance, physically correct shader/light/camera or perceived photorealism demonstrated by this image classification.','Any chosen algorithm based on results from this heldout source consumes it for model selection and must be challenged on a NEW source class and truly human scored owner production render.']}
 OUT.write_text(json.dumps(rep,indent=2)+'\n')
 content='''# New independent industrial photo evidence: PaDiM-style spatial source anomaly detector versus cheap controls\n\n**25 October 2026 — owner visual perception research. Status: PARTIAL, this analysis is complete.** A new third MVTec LOCO original product category, **Screw Bag**, was used to test whether a more specifically spatial industrial anomaly analyzer substantially improves on the poor generic image VLM/CLIP detection shown by the earlier *pushpins* and *splicing connectors* source experiments. This is one external new laboratory object family, **not** an unrelated manufacturer and not an owner mechanical warehouse render. Primary source [MVTec LOCO AD](https://www.mvtec.com/research-teaching/datasets/mvtec-loco-ad) (Bergmann et al., IJCV 2022), external source photo-label classes normal, logical anomalies and structural anomalies. Original source photos and pretrained model weights are **CC BY-NC-SA noncommercial** or separate model-source licenses, and no original media is placed into SWAAG project Git. The original public HF source mirror is pinned to revision `839fee8178c10d2e50afddc671238ba85d9975d9`.\n\nThe test selection was fixed by source-independent hash BEFORE inspecting images: **24 train-normal images**, **20 separate validation-normal for the cutoff**, **30 original heldout source-good**, **30 original heldout logical-defective**, and **30 original heldout structural-defective photos**. All 134 original source media files, roughly 194 MB, were checked against upstream byte sizes and retained with SHA-256 provenance outside Git. CPU-only on busy Nitro with no GPU, full ImageNet-1K official ResNet18 weights verified by SHA-256 and original preprocessor used for a 512D global model plus a 32-channel 28x28 normal-spatial Gaussian. Its features were fixed by layer1/2/3 pretrained representations, a seeded fixed 32-of-448 channel selection, and normal-only pixel-position covariance with regularization 0.01. Two predeclared spatial image scores—**the maximum Mahalanobis difference** and **the 95th percentile spatial difference**—were compared with the pretrained ResNet18 full-image cosine-memory baseline and a simple same-budget 2-by-4 tiled HSV histogram. These are **PaDiM-inspired probes**, not an official production implementation or a preexisting certified industrial anomaly classifier.\n\nAll four methods used the same 24 original normal-reference photographs and 20 untouched normal validation photographs for a fixed **95th percentile validation score threshold**. The raw source-image scores and thresholds for all 134 images were stored before any of the thirty good, thirty logical and thirty structural source-test labels were consulted for evaluation. No threshold was adapted to visible defects, and no anomaly was used in training.\n\n## Original heldout results with true alarms, misses and false alarms\n\nIn the following table, the **thirty source-good control photographs are distinct from training and validation**. The logical and structural positives are separate source classes. ROC AUC and image-stratified bootstrap intervals describe ranking on this original, one-product source corpus and do not supply a production decision threshold by themselves.\n\n| Fixed image analyzer | Original logical defects detected | Structural defects detected | False flags on 30 good controls | Missed of 60 anomalies | Pooled ROC AUC | Image-stratified bootstrap 95% AUC interval |\n|---|---:|---:|---:|---:|---:|---|\n'''+"\n".join(rows)+"\n\n"
 content+='''The companion `perceptual-mvtec-screwbag-new-spatial-anomaly-evidence-2026-10-25.json` retains the **actual original-source TP/FP/FN/TN separately** for 30 logical-positive versus the exact same 30 good controls, 30 structural-positive versus those controls, and 60 pooled positives versus those controls. It also retains the exact 95% binomial recall/specificity intervals and source-photo bootstrap intervals, original image/model SHA-256 provenance, documented CPU runtime/resource cost and noncommercial source rights. These are genuine original industry-inspired photographs and external labeled source good/defect cases, **not toy fixtures with metadata-derived gold**, but their source normal and anomaly labels were assigned by MVTec, not newly blindly audited by a qualified mechanical inspector. The copyright license forbids commercial use of original dataset media without additional permission.\n\n## Operational verdict\n\nPretrained image features and spatial normal-only models can only be assigned an automatic failure role if their **actual false alarms and misses on unseen target product photos** satisfy a separately declared operational risk budget. A spatial feature detector finding surface/texture differences still cannot prove correct screw count and arrangement, load-bearing tolerance, correct original warehouse pallet support or photo-realistic shaders and cameras. If it alerts on the final pixels, report the candidate visual problem for inspection; if it does not alert, return **not detected**, not certified correct. The original source CAD, assembly graph, actual three-dimensional triangle contacts and approved design remain the strongest physical correctness reference. This one independent product class only updates which visual model merits additional testing.\n\nOpen: a certified multi-manufacturer and owner-warehouse CAD-to-render test with genuine source part relationships, human-audited final visual defects, an independent more capable trained specialty vision model such as official PatchCore/EfficientAD, and source-matched natural bad-versus-good animation with exact human timing. Previously denied actions and uncertain Calendar submissions were not repeated. No production GPU services or customer-facing media were modified. **Research status PARTIAL.**\n'''
 REPORT.write_text(content)
 print('SOURCE_LINKED_NEW_INDEPENDENT_SPECIALIST_VS_GLOBAL_REPORT',OUT.name,'BYTES',OUT.stat().st_size,'MD',REPORT.stat().st_size)
if __name__=='__main__':main()
